'use client';

import { useState, useEffect, useCallback } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import { getMonth, getDate, getYear, parseISO, getDaysInMonth, format } from 'date-fns';
import { mockPrompts as lifePrompts } from '@/lib/mockData';
import { teleprompterScripts, defaultTeleprompterFallbackScript } from '@/lib/teleprompterScripts';
import { emotionTagsList, memoryCategoriesList, type EmotionTag, type MemoryCategory, type Prompt as LifePrompt } from '@/types';
import type { Memory, MediaAttachment } from '@/types';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Slider } from '@/components/ui/slider';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Carousel, CarouselContent, CarouselItem, type CarouselApi } from "@/components/ui/carousel";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '@/components/ui/tooltip';
import { Loader2, ArrowRight, ArrowLeft, Scissors, Sparkles, MapPin, Info, QrCode, Flag } from 'lucide-react';
import { useToast } from '@/hooks/use-toast';
import dynamic from 'next/dynamic';
import { useAuth } from '@/hooks/useAuth';
import { doc, getDoc, arrayUnion, arrayRemove, onSnapshot } from 'firebase/firestore';
import { db, storage } from '@/lib/firebase';
import { ref, uploadBytesResumable, getDownloadURL, deleteObject } from 'firebase/storage';
import { QrCodeDialog } from '@/components/prompts/QrCodeDialog';
import { AuthenticatedPageWrapper } from '@/components/layout/AuthenticatedPageWrapper';
import { saveMemory } from '@/actions/memoryActions';

const MediaCaptureControl = dynamic(
  () => import('@/components/memory/MediaRecorder').then((mod) => mod.MediaCaptureControl),
  {
    ssr: false,
    loading: () => <div className="h-48 flex items-center justify-center"><Loader2 className="animate-spin text-primary" /></div>
  }
);

const formatTime = (seconds: number) => {
    const totalSeconds = Math.round(seconds);
    const minutes = Math.floor(totalSeconds / 60);
    const remainingSeconds = totalSeconds % 60;
    return `${minutes.toString().padStart(2, '0')}:${remainingSeconds.toString().padStart(2, '0')}`;
};

function MemoryForm() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const { toast } = useToast();
  const { user, loading: authLoading } = useAuth();

  const editMemoryId = searchParams.get('editMemoryId') || undefined;
  const promptId = searchParams.get('promptId') || undefined;

  const prompt = lifePrompts.flatMap((p: LifePrompt) => [p, ...(p.subPrompts || [])]).find((p: LifePrompt) => p.id === promptId);
  const teleprompterScript = teleprompterScripts[promptId || ''] || defaultTeleprompterFallbackScript;
  const initialTitle = prompt?.text.en || searchParams.get('customPrompt') || '';

  const isEditing = !!editMemoryId;

  const [memoryToEdit, setMemoryToEdit] = useState<Memory | null>(null);
  const [isLoadingMemory, setIsLoadingMemory] = useState(isEditing);

  const [title, setTitle] = useState(initialTitle);
  const [description, setDescription] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<MemoryCategory | undefined>();
  const [location, setLocation] = useState('');
  const [selectedEmotionTags, setSelectedEmotionTags] = useState<EmotionTag[]>([]);

  const [selectedYear, setSelectedYear] = useState(new Date().getFullYear());
  const [selectedMonth, setSelectedMonth] = useState(getMonth(new Date()));
  const [selectedDay, setSelectedDay] = useState(getDate(new Date()));

  const [mediaPayload, setMediaPayload] = useState<{ file: File, type: 'video' | 'audio', duration: number } | null>(null);
  const [initialMedia, setInitialMedia] = useState<MediaAttachment | null>(null);
  const [trimValues, setTrimValues] = useState<[number, number]>([0, 0]);

  const [carouselApi, setCarouselApi] = useState<CarouselApi>();
  const [currentSlide, setCurrentSlide] = useState(0);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [uploadProgress, setUploadProgress] = useState<number | null>(null);
  const [isFlagged, setIsFlagged] = useState(false);
  const [isLoadingFlag, setIsLoadingFlag] = useState(true);
  const [qrCodeDialog, setQrCodeDialog] = useState<{ open: boolean; url: string; title: string; }>({ open: false, url: '', title: '' });

  useEffect(() => {
    if (authLoading || !user || !promptId) return;

    const userRef = doc(db, 'users', user.uid);
    const unsubscribe = onSnapshot(userRef, (docSnap) => {
        if (!docSnap.exists()) {
            setIsLoadingFlag(false);
            return;
        }

        const userData = docSnap.data();
        const newFlagState = userData.flaggedPrompts?.includes(promptId) || false;

        if (isLoadingFlag) {
            console.log(`TESTIMONY - flag-tc1-ts1 - START`);
            console.log(`State Before: Initial flag state is unknown.`);
            console.log(`Action: Listening for real-time updates.`);
            console.log(`State After: Initial state of prompt ${promptId} is isFlagged: ${newFlagState}.`);
            console.log(`TESTIMONY - flag-tc1-ts1 - END`);
            setIsLoadingFlag(false);
        } else if (isFlagged !== newFlagState) {
            const testStepId = newFlagState ? 'flag-tc1-ts4' : 'flag-tc1-ts6';
            console.log(`TESTIMONY - ${testStepId} - START`);
            console.log(`State Before: Flag state is isFlagged: ${isFlagged}.`);
            console.log(`Action: Received real-time update.`);
            console.log(`State After: Flag state updated to isFlagged: ${newFlagState}.`);
            console.log(`TESTIMONY - ${testStepId} - END`);
        }

        setIsFlagged(newFlagState);
    }, (error) => {
        console.error("Error listening for flag status:", error);
        toast({ title: 'Error', description: 'Could not sync flag status.', variant: 'destructive'});
        setIsLoadingFlag(false);
    });

    return () => unsubscribe();
  }, [promptId, user, authLoading, toast, isFlagged, isLoadingFlag]);

  const handleToggleFlag = async (event: React.MouseEvent) => {
    event.preventDefault();
    event.stopPropagation();
    if (!user || !promptId) return;

    const testStepId = isFlagged ? 'flag-tc1-ts5' : 'flag-tc1-ts3';
    console.log(`TESTIMONY - ${testStepId} - START`);
    console.log(`State Before: Prompt is ${isFlagged ? 'flagged' : 'unflagged'}.`);
    console.log(`Action: User clicked flag icon to ${isFlagged ? 'unflag' : 'flag'}.`);

    const userRef = doc(db, 'users', user.uid);
    try {
      await updateDoc(userRef, {
        flaggedPrompts: isFlagged ? arrayRemove(promptId) : arrayUnion(promptId)
      });
      toast({ title: isFlagged ? 'Prompt unflagged' : 'Prompt flagged', variant: 'success' });
    } catch (error) {
      console.error(`TESTIMONY - ${testStepId} - ERROR:`, error);
      toast({ title: 'Error', description: 'Could not update flag.', variant: 'destructive'});
    } finally {
      console.log(`TESTIMONY - ${testStepId} - END`);
    }
  };

  useEffect(() => {
    if (authLoading || !user || !editMemoryId) {
      setIsLoadingMemory(false);
      return;
    }

    const fetchMemory = async () => {
      // This now uses the server action
      const { success, data, message } = await getMemoryById(editMemoryId);
      if (success && data) {
        setMemoryToEdit(data as Memory);
      } else {
        toast({ title: 'Error', description: message, variant: 'destructive'});
        router.push('/timeline');
      }
      setIsLoadingMemory(false);
    };
    fetchMemory();
  }, [editMemoryId, user, authLoading, router, toast]);

  useEffect(() => {
    if (memoryToEdit) {
      if (!prompt) setTitle(memoryToEdit.title || '');
      setDescription(memoryToEdit.description || '');
      setSelectedCategory(memoryCategoriesList.find(c => c.id === memoryToEdit.category) || memoryCategoriesList[0]);
      setLocation(memoryToEdit.location || '');
      setSelectedEmotionTags((memoryToEdit.emotionTags || []).map(tagId => emotionTagsList.find(t => t.id === tagId)).filter(Boolean) as EmotionTag[]);
      if (memoryToEdit.date) {
        try {
          const date = parseISO(memoryToEdit.date);
          setSelectedYear(getYear(date));
          setSelectedMonth(getMonth(date));
          setSelectedDay(getDate(date));
        } catch (e) { console.error("Failed to parse date:", memoryToEdit.date); }
      }
      if (memoryToEdit.mediaAttachments?.[0]) {
        const m = memoryToEdit.mediaAttachments[0];
        setInitialMedia(m);
        setTrimValues([m.startTime || 0, m.endTime || m.duration || 0]);
      }
    }
  }, [memoryToEdit, prompt]);

  useEffect(() => {
    if (!carouselApi) return;
    const onSelect = () => setCurrentSlide(carouselApi.selectedScrollSnap());
    carouselApi.on("select", onSelect);
    onSelect();
    return () => { carouselApi.off("select", onSelect); };
  }, [carouselApi]);

  const handleMediaReady = useCallback((payload: any) => {
    setMediaPayload(payload ? { ...payload } : null);
    setTrimValues(payload ? [0, payload.duration] : [0, 0]);
  }, []);

 const handleShowQrCode = useCallback(() => {
    const testStepId = 'qr-tc1-ts1';
    console.log(`TESTIMONY - ${testStepId} - START`);
    console.log('State Before: QR dialog is not visible.');
    console.log('Action: User clicked QR code icon.');
    if (!promptId) return;
    const url = `${window.location.origin}/prompts/${promptId}`;
    setQrCodeDialog({ open: true, url, title: title || 'this prompt' });
    console.log(`State After: QR dialog is visible with URL: ${url}`);
    console.log(`TESTIMONY - ${testStepId} - END`);
}, [promptId, title]);

  const currentMediaDuration = mediaPayload?.duration || initialMedia?.duration || 0;

  const handleSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const testCaseId = isEditing ? 'e2e-edit-memory' : 'e2e-add-memory';
    setIsSubmitting(true);
    console.log(`TESTIMONY - ${testCaseId}-ts-submit - START`);

    try {
      if (!user) throw new Error("You must be logged in.");
      if (!title) {
        carouselApi?.scrollTo(0);
        throw new Error("Please give your memory a title.");
      }
      if (!mediaPayload?.file && !initialMedia) {
        carouselApi?.scrollTo(1);
        throw new Error("Please add media to your memory.");
      }

      let newOrUpdatedAttachments: MediaAttachment[] = memoryToEdit?.mediaAttachments || [];

      if (mediaPayload?.file) {
        const file = mediaPayload.file;
        const fileId = crypto.randomUUID();
        const fileExtension = file.name.split('.').pop() || 'tmp';
        const filePath = `users/${user.uid}/media/${fileId}.${fileExtension}`;
        const fileRef = ref(storage, filePath);

        console.log(`TESTIMONY - ${testCaseId}-ts-upload-media - START`);
        const uploadTask = uploadBytesResumable(fileRef, file);

        uploadTask.on('state_changed',
          (snapshot) => {
            const progress = (snapshot.bytesTransferred / snapshot.totalBytes) * 100;
            setUploadProgress(progress);
            console.log(`TESTIMONY - ${testCaseId}-ts-upload-progress - Progress: ${progress.toFixed(2)}%`);
          },
          (error) => {
            console.error(`TESTIMONY - ${testCaseId}-ts-upload-media - ERROR:`, error);
            throw new Error('File upload failed: ' + error.message);
          },
          async () => {
            const publicUrl = await getDownloadURL(uploadTask.snapshot.ref);
            console.log(`TESTIMONY - ${testCaseId}-ts-upload-media - END - URL: ${publicUrl}`);
            
            if (initialMedia?.url && initialMedia.url.includes('firebasestorage.googleapis.com')) {
                try {
                    const oldFileRef = ref(storage, initialMedia.url);
                    await deleteObject(oldFileRef);
                } catch (deleteError: any) {
                    if (deleteError.code !== 'storage/object-not-found') console.warn("Could not delete old media:", deleteError);
                }
            }

            newOrUpdatedAttachments = [{
              id: fileId,
              url: publicUrl,
              type: file.type.startsWith('video') ? 'video' : 'audio',
              filename: file.name,
            }];

            await finishSubmission(newOrUpdatedAttachments);
          }
        );
      } else {
        await finishSubmission(newOrUpdatedAttachments);
      }
    } catch (error: any) {
      toast({ title: "Error", description: error.message, variant: "destructive" });
      setIsSubmitting(false);
      setUploadProgress(null);
      console.error(`TESTIMONY - ${testCaseId}-ts-submit - FATAL_ERROR:`, error);
      console.log(`TESTIMONY - ${testCaseId}-ts-submit - END`);
    }
  };

  const finishSubmission = async (attachments: MediaAttachment[]) => {
    if (!user) return;
    const testCaseId = isEditing ? 'e2e-edit-memory' : 'e2e-add-memory';

    if (attachments.length > 0) {
        attachments[0] = {
          ...attachments[0],
          startTime: trimValues[0],
          endTime: trimValues[1],
          isTrimmed: trimValues[0] > 0 || (!!currentMediaDuration && trimValues[1] < currentMediaDuration),
          duration: currentMediaDuration
        };
    }

    const memoryData: Omit<Memory, 'id' | 'createdAt' | 'updatedAt'> = {
      title,
      date: new Date(selectedYear, selectedMonth, selectedDay).toISOString(),
      description,
      category: selectedCategory?.id || 'personal_reflection',
      location,
      emotionTags: selectedEmotionTags.map(t => t.id),
      promptId: promptId || memoryToEdit?.promptId,
      userId: user.uid,
      mediaAttachments: attachments,
    };

    console.log(`TESTIMONY - ${testCaseId}-ts-save-to-db - START`);
    const result = await saveMemory(memoryData, editMemoryId || null);
    console.log(`TESTIMONY - ${testCaseId}-ts-save-to-db - END`);

    if (result.success) {
      toast({ title: "Success", description: result.message, variant: 'success' });
      router.push('/timeline');
      router.refresh();
    } else {
      throw new Error(result.message);
    }

    setIsSubmitting(false);
    setUploadProgress(null);
    console.log(`TESTIMONY - ${testCaseId}-ts-submit - END`);
  }

  const toggleEmotionTag = (tag: EmotionTag) => {
    setSelectedEmotionTags(prev =>
      prev.some(t => t.id === tag.id) ? prev.filter(t => t.id !== tag.id) : [...prev, tag]
    );
  };

  const years = Array.from({ length: 101 }, (_, i) => new Date().getFullYear() - i);
  const months = Array.from({ length: 12 }, (_, i) => ({ value: i, label: format(new Date(2000, i, 1), 'MMMM') }));
  const days = Array.from({ length: getDaysInMonth(new Date(selectedYear, selectedMonth)) }, (_, i) => i + 1);

  const leftValueLabel = currentMediaDuration > 0 ? formatTime(trimValues[0]) : '';
  const rightValueLabel = currentMediaDuration > 0 ? formatTime(trimValues[1]) : '';
  const leftPosition = currentMediaDuration > 0 ? `calc(${(trimValues[0] / currentMediaDuration) * 100}% - ${leftValueLabel.length / 2}ch)` : '0%';
  const rightPosition = currentMediaDuration > 0 ? `calc(${(trimValues[1] / currentMediaDuration) * 100}% - ${rightValueLabel.length / 2}ch)` : '100%';

  if (isLoadingMemory || authLoading) {
      return (
        <div className="container mx-auto py-8 px-4 flex justify-center items-center h-[calc(100vh-8rem)]">
            <div className="flex flex-col items-center space-y-4">
                <Loader2 className="h-12 w-12 animate-spin text-primary" />
                <p className="text-muted-foreground">Loading...</p>
            </div>
        </div>
      );
  }

  return (
    <form onSubmit={handleSubmit}>
      <div className="max-w-3xl mx-auto py-8 px-4">
        <div className="flex justify-center mb-6 space-x-2">
          {[0, 1].map((step) => (
            <div key={step} className={`h-2 w-16 rounded-full transition-colors ${currentSlide === step ? 'bg-primary' : 'bg-secondary'}`} />
          ))}
        </div>

        <Carousel setApi={setCarouselApi} opts={{ watchDrag: false }} className="w-full">
          <CarouselContent>
            <CarouselItem>
              <Card>
                <CardHeader>
                    <div className="flex justify-between items-start">
                        <div>
                            <CardTitle>The Details</CardTitle>
                            <CardDescription>When, where, and how did this happen?</CardDescription>
                        </div>
                        {promptId && (
                            <TooltipProvider>
                                <div className="flex items-center space-x-2">
                                    <Tooltip><TooltipTrigger asChild><Button variant="ghost" size="icon" className="text-muted-foreground hover:text-primary"><Info className="h-5 w-5" /></Button></TooltipTrigger><TooltipContent side="bottom" align="end" className="max-w-xs"><p className="text-sm">{teleprompterScript}</p></TooltipContent></Tooltip>
                                    <Tooltip><TooltipTrigger asChild><Button variant="ghost" size="icon" className="text-muted-foreground hover:text-primary" onClick={(e) => { e.preventDefault(); e.stopPropagation(); handleShowQrCode(); }}><QrCode className="h-5 w-5" /></Button></TooltipTrigger><TooltipContent side="bottom" align="end"><p>Show QR code</p></TooltipContent></Tooltip>
                                    <Tooltip><TooltipTrigger asChild><Button type="button" variant="ghost" size="icon" onClick={handleToggleFlag} disabled={isLoadingFlag || authLoading}><Flag className={`h-5 w-5 transition-colors ${isFlagged ? 'fill-primary text-primary' : 'text-muted-foreground hover:text-primary'}`} /></Button></TooltipTrigger><TooltipContent side="bottom" align="end"><p>{isFlagged ? 'Unflag prompt' : 'Flag prompt'}</p></TooltipContent></Tooltip>
                                </div>
                            </TooltipProvider>
                        )}
                    </div>
                </CardHeader>
                <CardContent className="space-y-6">
                  <div className="space-y-2"><Label>Title</Label><Input name="title" placeholder="e.g. My 30th Birthday" value={title} onChange={e => setTitle(e.target.value)} required/></div>
                  <div className="space-y-2"><Label>Date</Label><div className="grid grid-cols-3 gap-2">
                      <Select value={selectedDay.toString()} onValueChange={v => setSelectedDay(parseInt(v))}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{days.map(d => <SelectItem key={d} value={d.toString()}>{d}</SelectItem>)}</SelectContent></Select>
                      <Select value={selectedMonth.toString()} onValueChange={v => setSelectedMonth(parseInt(v))}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{months.map(m => <SelectItem key={m.value} value={m.value.toString()}>{m.label}</SelectItem>)}</SelectContent></Select>
                      <Select value={selectedYear.toString()} onValueChange={v => setSelectedYear(parseInt(v))}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{years.map(y => <SelectItem key={y} value={y.toString()}>{y}</SelectItem>)}</SelectContent></Select>
                  </div></div>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2"><Label>Category</Label><Select value={selectedCategory?.id || ''} onValueChange={(val) => setSelectedCategory(memoryCategoriesList.find(c => c.id === val))}><SelectTrigger><SelectValue placeholder="Select Category" /></SelectTrigger><SelectContent>{memoryCategoriesList.map((cat) => (<SelectItem key={cat.id} value={cat.id}>{cat.label}</SelectItem>))}</SelectContent></Select></div>
                    <div className="space-y-2"><Label>Location</Label><div className="relative"><MapPin className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" /><Input name="location" className="pl-8" placeholder="London, UK" value={location} onChange={e => setLocation(e.target.value)} /></div></div>
                  </div>
                  <div className="space-y-2"><Label>Description</Label><Textarea name="description" placeholder="Describe the memory..." className="min-h-[120px]" value={description} onChange={e => setDescription(e.target.value)} /></div>
                  <div className="space-y-2"><Label>Emotions</Label><div className="flex flex-wrap gap-2">{emotionTagsList.map((tag: EmotionTag) => (<Button key={tag.id} type="button" variant={selectedEmotionTags.some(t => t.id === tag.id) ? 'default' : 'outline'} size="sm" onClick={() => toggleEmotionTag(tag)}>{tag.label}</Button>))}</div></div>
                </CardContent>
              </Card>
            </CarouselItem>
            <CarouselItem>
              <Card>
                <CardHeader><CardTitle>{isEditing ? 'Edit Media' : 'Add Media'}</CardTitle><CardDescription>{isEditing ? 'Replace or trim the existing media.' : 'Upload or record media.'}</CardDescription></CardHeader>
                <CardContent className="space-y-6">
                  <MediaCaptureControl onMediaReady={handleMediaReady} initialMedia={initialMedia ? { previewUrl: initialMedia.url, type: initialMedia.type, duration: initialMedia.duration } : null} trimValues={trimValues} />
                  {(mediaPayload || initialMedia) && currentMediaDuration > 0 && (
                      <div className="pt-4 space-y-4 border-t">
                          <Label className="flex items-center text-primary"><Scissors className="w-4 h-4 mr-2"/> Trim Clip</Label>
                          <div className="relative">
                              <div className="relative h-8">
                                  <span className="text-xs text-muted-foreground font-mono absolute" style={{ left: leftPosition }}>{leftValueLabel}</span>
                                  <span className="text-xs text-muted-foreground font-mono absolute" style={{ left: rightPosition }}>{rightValueLabel}</span>
                              </div>
                              <Slider min={0} max={currentMediaDuration} step={0.1} minStepsBetweenThumbs={1} value={trimValues} onValueChange={(v) => setTrimValues(v as [number, number])} aria-label="Video trim slider" />
                               <div className="flex justify-between mt-1">
                                  <span className="text-xs text-muted-foreground font-mono">{formatTime(0)}</span>
                                  <span className="text-xs text-muted-foreground font-mono">{currentMediaDuration ? formatTime(currentMediaDuration) : '00:00'}</span>
                              </div>
                          </div>
                      </div>
                  )}
                </CardContent>
              </Card>
            </CarouselItem>
          </CarouselContent>
        </Carousel>

        <QrCodeDialog open={qrCodeDialog.open} url={qrCodeDialog.url} title={qrCodeDialog.title} onClose={() => setQrCodeDialog({ open: false, url: '', title: '' })} />

        <div className="flex justify-between mt-8 px-1">
          <Button type="button" variant="ghost" onClick={() => currentSlide === 0 ? router.back() : carouselApi?.scrollPrev()} disabled={isSubmitting}>
            {currentSlide === 0 ? 'Cancel' : <><ArrowLeft className="w-4 h-4 mr-2" /> Back</>}
          </Button>
          {currentSlide === 0 ? (
             <Button type="button" onClick={(e) => {e.preventDefault(); carouselApi?.scrollNext();}} disabled={isSubmitting}>
              <span className="mr-2">Next</span> <ArrowRight className="w-4 h-4" />
             </Button>
          ) : (
            <Button type="submit" disabled={isSubmitting || authLoading} className="min-w-[120px]">
              {isSubmitting ? 
                <><Loader2 className="animate-spin w-4 h-4 mr-2" /> {uploadProgress !== null ? `${Math.round(uploadProgress)}%` : 'Saving...'}</> : 
                <><Sparkles className="w-4 h-4 mr-2" /> {isEditing ? 'Update Memory' : 'Save Memory'}</>}
            </Button>
          )}
        </div>
      </div>
    </form>
  );
}

export default function AddMemoryPage() {
    return (
      <AuthenticatedPageWrapper>
        <MemoryForm />
      </AuthenticatedPageWrapper>
    )
}
